const input = require("fs").readFileSync(0, "utf8");

function factorial(n) {
  let result = 1;
  for (let i = 1; i <= n; i++) {
    result *= i;
  }
  return result;
}

const n = parseInt(input.trim(), 10);
console.log(factorial(n));

