go.solution:
package main

import "fmt"

func factorial(n int) int {
	result := 1
	for i := 1; i <= n; i++ {
		result *= i
	}
	return result
}

func main() {
	var n int
	fmt.Scan(&n)
	fmt.Println(factorial(n))
}
